# -*- coding: utf-8 -*-
"""Scenarios S11-S30, extra candidates, initiatives and KRIs for the 30-scenario assessment."""
from data import P

NEW = []
def S(**kw):
    NEW.append(kw)

S(id="S11", ref="MED-CYR-04", name="API key or secret exposed in code, logs or configuration enables direct data access",
  statement="An opportunistic actor finds an API key, database connection string or cloud access token that a developer committed to a code repository, left in a log or embedded in a configuration file, and uses it to call MediBec's EHR integration or cloud storage APIs directly, extracting patient data without passing through user authentication.",
  stakeholders="Application development team; CIO; Cybersecurity lead; Privacy officer; cloud provider; integration partners.",
  background="MediBec has in-house software/application development and database staff (E3). API key management and repository scanning are listed as an auditable area (E7) and as scenario MED-CYR-04 (E8). No secret-management tooling is evidenced.",
  threat_source="Opportunistic actor scanning public repositories and paste sites; cybercriminal.",
  threat_event="Use of a leaked credential against an API.",
  vulns=["No secret scanning or vault evidenced (E7)", "Long-lived API keys without rotation (Analyst assumption)", "API calls not monitored for anomalous volume (E7)", "Development practices and repository visibility unknown (Evidence gap)"],
  assets="CJ1 EHR integration APIs; CJ7 cloud storage.", processes="Application integration, data exchange with partners.",
  controls=["Encrypted storage (E2 - does not protect against valid-key access)"],
  narrative="A developer pushes a test script containing a storage access key to a public repository. Within hours automated scanners harvest it; an actor lists and downloads patient export files and queries an integration endpoint until the key is revoked weeks later.",
  sequence=["Discovery - automated secret scanning of public sources", "Initial access - valid API key", "Collection - API enumeration and downloads", "Exfiltration - bulk transfer", "Detection - late, via billing anomaly or external notice", "Business impact - privacy breach"],
  consequences={"Confidentiality/privacy": "Bulk access to data reachable by the key.", "Integrity": "Possible if key has write scope.", "Availability": "Key revocation may break integrations.", "Operations": "Emergency rotation across systems.", "Financial": "Notification and forensic costs.", "Regulatory": "Reportable confidentiality incident likely.", "Reputation": "Moderate to high.", "Safety": "Low."},
  params={"PbA": P(0.45, "Plausible", "Secret leakage is common where development occurs; MediBec's development footprint is uncertain.", "E3, E7", "Low"),
          "Pbx": P(0.45, "Plausible", "No vault, scanning or rotation evidenced.", "E7", "Low"),
          "De": P(0.50, "Material", "Data reachable by one key.", "E7", "Medium"),
          "Dm": P(0.80, "Severe", "Key with broad EHR or storage scope.", "E1", "Medium"),
          "Th": P(0.40, "Limited", "API monitoring not evidenced.", "E7", "Low"),
          "Mu": P(0.75, "High", "Integrations support EHR and image exchange.", "E2", "Medium")},
  cvss="CVSS:4.0/AV:N/AC:L/AT:P/PR:N/UI:N/VC:H/VI:L/VA:N/SC:N/SI:N/SA:N",
  cvss_note="Representative weakness: hard-coded credential (CWE-798). AT:P the attacker must first obtain the leaked secret; PR:N once held, no further privileges needed; VC:H data access; VI:L limited write scope.",
  red_p=0.85, red_i=0.60, inits=["I03", "I08", "I14"],
  treatment="Secret scanning in repositories and pipelines, central vault with short-lived tokens and rotation (I14); API anomaly monitoring (I03); scoped cloud keys (I08).",
  owner="CIO (Application development)", horizon="3-9 months")

S(id="S12", ref="MED-CYR-05", name="Clinic Wi-Fi compromise or rogue access point gives access to the clinical network",
  statement="An attacker in or near a clinic exploits weak wireless security, an unsegmented guest network or a rogue access point to join the clinic network, intercept credentials and reach EHR workstations and local storage.",
  stakeholders="Clinic managers; Infrastructure team; Cybersecurity lead; patients and visitors; Clinical Ops.",
  background="Wireless and guest networks are an auditable area; WPA settings, rogue AP scans and guest segmentation tests are expected evidence but none is documented (E7). Clinics are geographically dispersed (E1).",
  threat_source="Local attacker (visitor, patient, passer-by) or opportunistic cybercriminal.",
  threat_event="Unauthorized wireless access and lateral movement.",
  vulns=["Guest and clinical Wi-Fi segmentation not evidenced (E7)", "Wireless standard and key management unknown (Evidence gap)", "No rogue AP detection evidenced", "Flat clinic LAN (Analyst assumption, see S7)"],
  assets="Clinic LAN; CJ1 EHR workstations; local clinic storage.", processes="Clinic operations, EHR access at point of care.",
  controls=["Firewalls and IDS/IPS at the Montreal hub (E2 - clinic-level coverage unknown)"],
  narrative="A pre-shared Wi-Fi key posted in a staff room is reused on the guest network, which routes to the clinic LAN. An attacker in the waiting room scans the network, finds a file share on the local storage unit and a workstation with an open remote desktop service.",
  sequence=["Initial access - weak/shared Wi-Fi key or rogue AP", "Discovery - scan clinic LAN", "Credential access - interception of cleartext protocols", "Lateral movement - to workstation or storage", "Collection - local patient files", "Detection - unlikely at clinic level", "Business impact - local breach or foothold for S2"],
  consequences={"Confidentiality/privacy": "Local patient files; intercepted credentials.", "Integrity": "Low.", "Availability": "Low unless used for S2.", "Operations": "Wi-Fi reconfiguration at all clinics.", "Financial": "Moderate.", "Regulatory": "Possible reportable incident.", "Reputation": "Moderate.", "Safety": "Indirect."},
  params={"PbA": P(0.40, "Plausible", "Requires physical proximity; clinics have public waiting rooms.", "E1", "Low"),
          "Pbx": P(0.45, "Plausible", "Wireless controls unknown.", "E7", "Low"),
          "De": P(0.40, "Moderate", "Access limited to one clinic.", "E1", "Medium"),
          "Dm": P(0.75, "Severe", "Foothold leading to network-wide compromise.", "E2", "Medium"),
          "Th": P(0.40, "Limited", "No clinic-level wireless monitoring evidenced.", "E7", "Low"),
          "Mu": P(0.70, "High", "Clinic networks carry point-of-care EHR access.", "E1", "Medium")},
  cvss="CVSS:4.0/AV:A/AC:L/AT:N/PR:N/UI:N/VC:L/VI:L/VA:N/SC:H/SI:L/SA:L",
  cvss_note="Representative weakness: weak wireless authentication with guest-to-internal routing. AV:A adjacent (radio range); VC/VI:L on the WLAN itself; SC:H clinical systems reachable behind it.",
  red_p=0.80, red_i=0.65, inits=["I03", "I06"],
  treatment="WPA3-Enterprise for staff, isolated internet-only guest Wi-Fi, rogue AP detection and NAC (I06); monitoring of clinic segments (I03).",
  owner="CIO (Infrastructure)", horizon="6-18 months")

S(id="S13", ref="MED-CYR-10", name="DDoS attack disrupts online booking, patient portal and communications",
  statement="A hacktivist or extortion group floods MediBec's internet-facing services with traffic, making online appointment booking, patient records access and external communications unavailable for hours or days and pushing volume to clinic phone lines.",
  stakeholders="Clinic managers; Communications; CIO; ISP and hosting providers; patients.",
  background="MED-CYR-10 identifies online services for appointments, records access and communications (E8). No DDoS protection, CDN or WAF is documented (E2).",
  threat_source="Hacktivist or DDoS-for-extortion group.",
  threat_event="Volumetric or application-layer denial of service.",
  vulns=["No DDoS mitigation service evidenced", "Single internet egress via Montreal hub (E2)", "No provider coordination plan evidenced"],
  assets="CJ3 online services; internet connectivity for clinics.", processes="Appointment booking, patient communications.",
  controls=["Firewalls, IDS/IPS (E2 - not designed for volumetric attacks)"],
  narrative="Following media coverage of healthcare, a hacktivist botnet targets MediBec's booking site. The shared internet link saturates, also degrading clinic access to cloud services routed through Montreal.",
  sequence=["Reconnaissance - identify public services", "Attack - volumetric and HTTP flood", "Impact - saturation of shared link", "Detection - users report outage", "Response - ISP engagement without pre-arranged mitigation", "Business impact - hours to days of degraded service"],
  consequences={"Confidentiality/privacy": "None.", "Integrity": "None.", "Availability": "Online services unavailable; cloud access degraded.", "Operations": "Phone and front-desk overload.", "Financial": "Lost bookings.", "Regulatory": "Low.", "Reputation": "Moderate.", "Safety": "Low - clinics continue in person."},
  params={"PbA": P(0.50, "Plausible", "DDoS campaigns against healthcare occur; MediBec profile moderate.", "E4", "Low"),
          "Pbx": P(0.60, "Likely", "No mitigation evidenced.", "E2", "Medium"),
          "De": P(0.30, "Limited", "Hours of online unavailability.", "E8", "Medium"),
          "Dm": P(0.55, "Material", "Multi-day disruption including cloud access.", "E2", "Low"),
          "Th": P(0.45, "Moderate", "Clinics can operate without online booking.", "E1", "Medium"),
          "Mu": P(0.55, "Moderate", "Online services useful but not essential to care.", "E8", "Low")},
  cvss="CVSS:4.0/AV:N/AC:L/AT:N/PR:N/UI:N/VC:N/VI:N/VA:H/SC:N/SI:N/SA:N",
  cvss_note="Limited applicability: volumetric DDoS exploits capacity, not a software flaw. Representative weakness: service without rate limiting or upstream mitigation (CWE-770). Availability only.",
  red_p=0.80, red_i=0.70, inits=["I11", "I15"],
  treatment="Upstream DDoS mitigation, CDN and WAF for public services, separate egress for clinic cloud traffic (I15); provider escalation and communications playbook (I11).",
  owner="CIO", horizon="0-6 months")

S(id="S14", ref="Annex B #71", name="Business e-mail compromise diverts vendor or billing payments",
  statement="A fraudster spoofs or compromises a supplier or executive mailbox and instructs MediBec finance staff to change bank details or pay a fraudulent invoice, because payment-change verification and e-mail authentication are weak, resulting in direct financial loss.",
  stakeholders="Finance lead; accounts payable; CFO; suppliers; Cybersecurity lead; bank.",
  background="Billing and administrative systems are central (E1); phishing lures already target billing staff (E6). E-mail authentication (DMARC) and payment verification procedures are not documented.",
  threat_source="Organized fraud group.", threat_event="Fraudulent payment instruction.",
  vulns=["No out-of-band payment-change verification evidenced", "DMARC enforcement unknown", "Billing staff targeted by phishing (E6)"],
  assets="CJ4 billing and accounts payable.", processes="Supplier payments, patient refunds.",
  controls=["E-mail filtering (E2 - effectiveness unknown)"],
  narrative="A look-alike supplier domain sends an updated banking form before a large equipment invoice. Accounts payable updates the vendor record by e-mail; CAD 180,000 is transferred before the real supplier chases payment.",
  sequence=["Reconnaissance - identify suppliers and invoice cycles", "Initial contact - spoofed or compromised mailbox", "Manipulation - bank-detail change", "Impact - fraudulent transfer", "Detection - supplier non-payment complaint", "Business impact - financial loss"],
  consequences={"Confidentiality/privacy": "Low.", "Integrity": "Vendor master data altered.", "Availability": "None.", "Operations": "Supplier relationship strain.", "Financial": "Direct loss, often unrecoverable.", "Regulatory": "Low.", "Reputation": "Low to moderate.", "Safety": "None."},
  params={"PbA": P(0.65, "Likely", "BEC is among the most frequent fraud types; billing staff already targeted.", "E6", "Medium"),
          "Pbx": P(0.40, "Moderate", "Verification procedures unknown.", "E1", "Low"),
          "De": P(0.35, "Moderate", "One diverted payment.", "E1", "Medium"),
          "Dm": P(0.60, "Material", "Several large payments diverted.", "E3", "Low"),
          "Th": P(0.45, "Moderate", "Bank recall possible if detected quickly.", "E1", "Low"),
          "Mu": P(0.55, "Moderate", "Financial, not clinical, process.", "E1", "Medium")},
  cvss="CVSS:4.0/AV:N/AC:L/AT:N/PR:N/UI:A/VC:N/VI:L/VA:N/SC:N/SI:N/SA:N",
  cvss_note="Limited applicability: payment fraud is a process weakness. Representative weakness: spoofable sender domain without enforced DMARC. UI:A staff must act on the instruction; VI:L data changed. The low score understates business impact - rely on damage estimates.",
  red_p=0.80, red_i=0.60, inits=["I12", "I16"],
  treatment="Mandatory call-back verification on bank-detail changes and dual approval above threshold, DMARC enforcement, BEC detection (I16); finance-specific awareness (I12).",
  owner="Finance lead (CFO)", horizon="0-3 months")

S(id="S15", ref="Annex B #7", name="Lost or stolen tablet or handheld exposes patient data",
  statement="A clinician's tablet or handheld used for EHR access is lost or stolen; because device encryption, screen lock and remote wipe are not centrally enforced, patient data cached on the device or accessible through saved sessions is exposed.",
  stakeholders="Clinicians; clinic managers; Privacy officer; IT support; patients.",
  background="Workstations, tablets and handheld devices support EHR access (E2). Encrypted storage is documented for central stores, not for mobile devices; mobile device management is not evidenced.",
  threat_source="Opportunistic thief; accidental loss.", threat_event="Physical loss of a device with data or live sessions.",
  vulns=["MDM, device encryption and remote wipe not evidenced", "Persistent EHR sessions on mobile devices (Analyst assumption)", "Loss-reporting procedure unknown"],
  assets="Mobile endpoints; CJ1 EHR data cached or accessible.", processes="Point-of-care documentation.",
  controls=["Encrypted central storage (E2)"],
  narrative="A tablet is stolen from a car. It has no enforced PIN and holds downloaded referral letters; the EHR app remains logged in. Loss is reported two days later.",
  sequence=["Loss or theft of device", "Access - no lock or weak PIN", "Collection - cached files and active sessions", "Detection - staff report, often delayed", "Response - account revocation, breach assessment", "Business impact - limited privacy breach"],
  consequences={"Confidentiality/privacy": "Records cached on one device.", "Integrity": "Low.", "Availability": "Device replacement.", "Operations": "Minor.", "Financial": "Low.", "Regulatory": "Breach assessment required; may be reportable.", "Reputation": "Low to moderate.", "Safety": "None."},
  params={"PbA": P(0.70, "Likely", "Across 10 clinics, some device loss each year is near certain.", "E1, E2", "Medium"),
          "Pbx": P(0.30, "Limited", "Some protection may exist but is not evidenced.", "E2", "Low"),
          "De": P(0.25, "Limited", "Small number of records.", "E2", "Medium"),
          "Dm": P(0.55, "Material", "Live EHR session allows wider access.", "E2", "Low"),
          "Th": P(0.45, "Moderate", "Accounts can be revoked centrally.", "E2", "Low"),
          "Mu": P(0.60, "Moderate", "Supports but is not essential to care.", "E2", "Medium")},
  cvss="CVSS:4.0/AV:P/AC:L/AT:N/PR:N/UI:N/VC:H/VI:N/VA:N/SC:N/SI:N/SA:N",
  cvss_note="Representative weakness: missing encryption of sensitive data at rest on the device (CWE-311). AV:P physical possession required; confidentiality only.",
  red_p=0.75, red_i=0.80, inits=["I17"],
  treatment="MDM with enforced encryption, PIN, session timeout, remote wipe and loss-reporting workflow (I17).",
  owner="CIO (Support)", horizon="3-9 months")

S(id="S16", ref="Annex B #5, #49", name="Loss of the Montreal hub or WAN isolates clinics from central clinical systems",
  statement="A carrier failure, cyberattack on network devices or data-centre incident takes the Montreal hub or WAN offline; because clinics depend on a single hub without tested redundancy or local fallback, EHR, imaging, lab and pharmacy access is lost at all ten clinics simultaneously.",
  stakeholders="CIO; Infrastructure; Clinical Ops; clinic managers; telecom carriers; Executive leadership.",
  background="All clinics connect via WAN to the primary hub in Montreal where the main data centre is located (E2). Redundancy, alternate site and failover testing are not documented; data-centre outage was screened out in the 10-scenario assessment and is now included as a resilience scenario.",
  threat_source="Accidental/environmental event, carrier failure, or attacker targeting network infrastructure.",
  threat_event="Enterprise-wide loss of connectivity or hosting.",
  vulns=["Single hub and possibly single carrier (Analyst assumption)", "Firewall redundancy unknown (Annex B #5)", "No alternate processing site evidenced", "Clinic downtime procedures untested (E7)"],
  assets="CJ6 data centre and WAN; all crown jewels dependent on them.", processes="All clinical and administrative services.",
  controls=["High-speed fibre links (E2)", "Off-site backups (E2 - restore time unknown)"],
  narrative="A fibre cut and simultaneous failure of the primary firewall pair leave all clinics without EHR for 14 hours. Clinics switch to paper, cannot view prior imaging or medication history, and postpone non-urgent appointments.",
  sequence=["Trigger - carrier cut, device failure or attack on edge devices", "Impact - WAN/hub unavailable", "Detection - immediate", "Response - carrier escalation, manual workarounds", "Recovery - hours to days", "Business impact - network-wide clinical disruption"],
  consequences={"Confidentiality/privacy": "None.", "Integrity": "Paper records to reconcile afterwards.", "Availability": "All central systems unreachable.", "Operations": "Network-wide degraded care.", "Financial": "Lost activity, overtime.", "Regulatory": "Continuity obligations.", "Reputation": "Moderate.", "Safety": "Missing history at point of care."},
  params={"PbA": P(0.35, "Plausible", "Multi-hour outages of a single hub occur over a 12-month horizon.", "E2", "Low"),
          "Pbx": P(0.50, "Plausible", "Redundancy not evidenced.", "E2", "Low"),
          "De": P(0.55, "Material", "Hours of network-wide outage.", "E1", "Medium"),
          "Dm": P(0.85, "Severe", "Multi-day loss of the hub.", "E2", "Medium"),
          "Th": P(0.35, "Weak", "No alternate site or tested downtime procedures.", "E7", "Medium"),
          "Mu": P(0.95, "Mission-critical", "Hub serves every clinic.", "E2", "High")},
  cvss="CVSS:4.0/AV:N/AC:L/AT:P/PR:N/UI:N/VC:N/VI:N/VA:H/SC:N/SI:N/SA:H",
  cvss_note="Limited applicability: architectural dependency, largely non-malicious. Representative weakness: denial of service against a single edge device with no redundancy (AT:P specific conditions); VA:H and SA:H for downstream systems.",
  red_p=0.70, red_i=0.65, inits=["I11", "I18"],
  treatment="Dual carriers / SD-WAN, firewall high availability, cloud or secondary-site failover for EHR read access (I18); tested clinic downtime procedures (I11).",
  owner="CIO (Infrastructure) with Clinical Ops", horizon="6-24 months")

S(id="S17", ref="Annex B #55, #111", name="Unmanaged patient data on local clinic storage is exposed or lost",
  statement="Patient exports, scanned documents and imaging copies accumulate on local clinic storage units outside central access control, retention and monitoring; an insider, intruder or misconfigured share exposes them, or they are lost without backup.",
  stakeholders="Clinic managers; Privacy officer; CIO; Infrastructure; patients.",
  background="Local clinic storage units exist alongside the central data centre (E2); students are asked where copies, exports and local records are stored (E4). Backup jobs for clinic storage have failed in the exercise (E6).",
  threat_source="Curious or malicious insider; intruder; accidental misconfiguration.", threat_event="Unauthorized access to or loss of locally stored data.",
  vulns=["Data sprawl without inventory (E4)", "Permissive share permissions (Analyst assumption)", "Retention schedule not evidenced", "Local backup reliability questionable (E6)"],
  assets="Local clinic storage; copies of CJ1/CJ2 data.", processes="Clinic administration, referrals, scanning.",
  controls=["Encrypted storage (E2)", "On-site and off-site backups (E2)"],
  narrative="A shared folder 'Scans' on a clinic storage unit is readable by all domain users and contains eight years of referral letters. A compromised account indexes it; separately, a disk failure destroys files that were never backed up.",
  sequence=["Condition - data accumulated locally", "Access - broad share permissions or compromised account", "Collection - bulk copy", "Detection - rarely", "Business impact - privacy breach or data loss"],
  consequences={"Confidentiality/privacy": "Years of local records exposed.", "Integrity": "Unverified duplicate records.", "Availability": "Loss of locally held data.", "Operations": "Clean-up effort.", "Financial": "Notification costs.", "Regulatory": "Retention and safeguarding obligations.", "Reputation": "Moderate.", "Safety": "Low."},
  params={"PbA": P(0.45, "Plausible", "Local storage in 10 clinics; insiders and intruders both relevant.", "E2, E4", "Low"),
          "Pbx": P(0.45, "Plausible", "Access controls and inventory unknown.", "E4", "Low"),
          "De": P(0.40, "Moderate", "One clinic's local data.", "E2", "Medium"),
          "Dm": P(0.70, "Severe", "Multiple clinics' historical data.", "E2", "Low"),
          "Th": P(0.40, "Limited", "No monitoring of local storage.", "E4", "Low"),
          "Mu": P(0.65, "Moderate-high", "Supports clinic operations.", "E2", "Medium")},
  cvss="CVSS:4.0/AV:A/AC:L/AT:N/PR:L/UI:N/VC:H/VI:L/VA:L/SC:N/SI:N/SA:N",
  cvss_note="Representative weakness: incorrect default permissions on network shares (CWE-276). AV:A clinic network; PR:L any domain user.",
  red_p=0.70, red_i=0.70, inits=["I17", "I19"],
  treatment="Data discovery, consolidation of local data into managed central stores, least-privilege shares, retention schedule (I19); encrypted and managed endpoints/storage (I17).",
  owner="Privacy officer with CIO", horizon="3-12 months")

