S(id="S26", ref="Annex B #141", name="Staff paste patient data into unapproved generative-AI tools",
  statement="Clinicians and administrative staff use public generative-AI tools to summarize notes, draft letters or translate documents, pasting identifiable patient information into services whose data retention, training use and location MediBec has not assessed, resulting in uncontrolled disclosure of health information.",
  stakeholders="Clinicians; administrative staff; Privacy officer; CIO; Legal; AI service providers.",
  background="Health information is highly sensitive (E1) and privacy controls are a priority in the appetite statement (E5). No AI acceptable-use policy or approved tool is documented.",
  threat_source="Well-intentioned insider; AI service provider handling.", threat_event="Transfer of personal health information to an unapproved third party.",
  vulns=["No AI acceptable-use policy evidenced", "No approved alternative tool", "Web DLP / category controls not evidenced", "Awareness content does not cover AI (Analyst assumption)"],
  assets="CJ1 clinical notes and letters.", processes="Documentation, correspondence, translation.",
  controls=["Privacy and compliance function (s.4)"],
  narrative="Clinicians use a free chatbot to turn dictated notes into referral letters. Over months, thousands of identifiable notes are submitted to a service that retains prompts outside Canada.",
  sequence=["Use - staff submit PHI to external AI", "Exposure - data retained by provider", "Detection - audit or complaint", "Response - privacy assessment", "Business impact - systemic privacy non-compliance"],
  consequences={"Confidentiality/privacy": "Systemic uncontrolled transfer.", "Integrity": "AI-generated errors in records.", "Availability": "None.", "Operations": "Policy change and retraining.", "Financial": "Legal costs.", "Regulatory": "Cross-border transfer and consent issues (counsel to confirm).", "Reputation": "Moderate to high.", "Safety": "Possible clinical errors from unchecked AI output."},
  params={"PbA": P(0.80, "Very likely", "Generative-AI use among clinicians is widespread by 2026.", "E1", "Medium"),
          "Pbx": P(0.55, "Moderate-high", "No policy or technical controls evidenced.", "E5", "Low"),
          "De": P(0.35, "Moderate", "Limited volume, low misuse likelihood.", "E1", "Low"),
          "Dm": P(0.65, "Material", "Systemic transfer plus clinical errors.", "E5", "Low"),
          "Th": P(0.40, "Limited", "No visibility of AI use.", "E5", "Low"),
          "Mu": P(0.70, "High", "Clinical documentation.", "E1", "Medium")},
  cvss="CVSS:4.0/AV:N/AC:L/AT:P/PR:L/UI:N/VC:H/VI:N/VA:N/SC:N/SI:N/SA:N",
  cvss_note="Limited applicability: policy and data-governance gap. Representative weakness: exposure of sensitive information to an unauthorized actor via unrestricted egress (CWE-200). AT:P - harm depends on provider retention.",
  red_p=0.65, red_i=0.55, inits=["I09", "I12", "I20"],
  treatment="AI acceptable-use policy, sanctioned privacy-assessed AI tool, web category controls and DLP for AI sites (I20, I09), training (I12).",
  owner="Privacy officer with CMO", horizon="0-6 months")

S(id="S27", ref="Annex B #96 (social engineering)", name="Help-desk impersonation leads to MFA reset and account takeover",
  statement="An attacker phones the IT help desk impersonating a clinician or manager, uses publicly available details to pass weak identity checks, and has the password and MFA device reset, taking over the account and accessing EHR and remote access.",
  stakeholders="IT support/help desk; Cybersecurity lead; clinicians; CIO.",
  background="IT support is part of the 15-person IT team (E3). Help-desk identity verification is not documented. Remote access relies on MFA push (E6), which a reset defeats.",
  threat_source="Social-engineering-capable cybercriminal group.", threat_event="Fraudulent credential and MFA reset.",
  vulns=["Help-desk verification based on knowable data (Analyst assumption)", "No manager or video verification for MFA resets", "No alerting on MFA device changes (E7)"],
  assets="CJ5 identity; CJ1 EHR.", processes="Account support.",
  controls=["MFA push (E6)"],
  narrative="Posing as a physician travelling to a conference, the caller gives employee number and date of hire found online and asks for an MFA reset. The attacker enrols their own phone and logs in within minutes.",
  sequence=["Reconnaissance - staff details from public sources", "Social engineering - help-desk call", "Account takeover - new MFA enrolled", "Access - EHR and remote access", "Escalation - toward S2 or data theft", "Detection - legitimate user locked out", "Business impact - breach or intrusion"],
  consequences={"Confidentiality/privacy": "EHR access under a clinician identity.", "Integrity": "Possible record changes.", "Availability": "User lockout.", "Operations": "Help-desk process change.", "Financial": "Moderate.", "Regulatory": "Reportable if data accessed.", "Reputation": "Moderate.", "Safety": "Indirect."},
  params={"PbA": P(0.55, "Plausible", "Help-desk social engineering is an active technique against healthcare.", "E4", "Low"),
          "Pbx": P(0.50, "Plausible", "Verification procedures unknown.", "E3", "Low"),
          "De": P(0.55, "Material", "One account's reach.", "E6", "Medium"),
          "Dm": P(0.90, "Extreme", "Privileged account leads to enterprise compromise.", "E1", "Medium"),
          "Th": P(0.40, "Limited", "MFA change not monitored.", "E7", "Low"),
          "Mu": P(0.85, "Very high", "Identity gateway.", "E2", "High")},
  cvss="CVSS:4.0/AV:N/AC:L/AT:N/PR:N/UI:A/VC:H/VI:H/VA:L/SC:H/SI:L/SA:L",
  cvss_note="Limited applicability: process weakness. Representative weakness: weak authentication of the account-recovery process (CWE-640). UI:A help-desk agent acts.",
  red_p=0.80, red_i=0.60, inits=["I01", "I12", "I21"],
  treatment="Strong help-desk verification (call-back, manager approval, video ID) for resets (I21), phishing-resistant authenticators that cannot be re-enrolled by phone (I01), alerts on MFA changes and awareness (I12).",
  owner="CIO (Support)", horizon="0-3 months")

